public class PureFiltersTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            java.util.List<Integer> input =
                    new java.util.ArrayList<>(java.util.Arrays.asList(3, -1, 0, -7, 5));
            java.util.List<Integer> result = PureFilters.withoutNegatives(input);
            check("negatives removed, order kept", "[3, 0, 5]",
                    result == null ? "null" : result.toString());
            check("input list is unchanged (pure function)", "[3, -1, 0, -7, 5]",
                    input.toString());
            check("result is a new list, not the input object", false, result == input);

            check("zero counts as non-negative", "[0, 0]",
                    String.valueOf(PureFilters.withoutNegatives(
                            java.util.Arrays.asList(0, -2, 0))));
            check("all negatives give an empty list", "[]",
                    String.valueOf(PureFilters.withoutNegatives(
                            java.util.Arrays.asList(-1, -2, -3))));
            check("empty input gives an empty list", "[]",
                    String.valueOf(PureFilters.withoutNegatives(
                            java.util.Collections.emptyList())));
            check("nothing to remove still returns everything", "[7, 8]",
                    String.valueOf(PureFilters.withoutNegatives(
                            java.util.Arrays.asList(7, 8))));
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception -- " + e.getClass().getSimpleName());
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

