public class PureFilters {

    public static java.util.List<Integer> withoutNegatives(java.util.List<Integer> nums) {
        java.util.List<Integer> result = new java.util.ArrayList<>();
        for (Integer n : nums) {
            if (n >= 0) {
                result.add(n);
            }
        }
        return result;
    }
}
